#!/usr/bin/env node
/**
 * compare-explorer-output.js
 *
 * Compares the HTML generated by the current branch's blueprint-explorer build
 * against the baseline HTML committed to main in packages/explorer/.
 *
 * Extracts baseline files from git (no checkout required), runs the build into
 * a temp dir, then diffs each corresponding file pair and reports matches,
 * diffs, and missing files.
 *
 * Usage:
 *   node scripts/compare-explorer-output.js              # build + compare
 *   node scripts/compare-explorer-output.js --skip-build # compare only (reuse last build)
 *   node scripts/compare-explorer-output.js --verbose    # show full diff output
 */

import { execFileSync, spawnSync } from 'child_process';
import { mkdirSync, writeFileSync, existsSync, cpSync } from 'fs';
import { resolve, dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { tmpdir } from 'os';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT      = resolve(__dirname, '..');
const node      = process.execPath;

const skipBuild = process.argv.includes('--skip-build');
const verbose   = process.argv.includes('--verbose');

const BASELINE_DIR = join(tmpdir(), 'snb-baseline');
const CURRENT_DIR  = join(tmpdir(), 'snb-current');

// ── Path mapping ──────────────────────────────────────────────────────────────
// Each entry: [path within packages/explorer/ on main, path within CURRENT_DIR]

const TOOL_DIRS = [
  ['tools/api-reference',    'api-reference'],
  ['tools/client-reference', 'client-reference'],
  ['tools/data-dictionaries','data-dictionaries'],
  ['tools/event-catalog',    'event-catalog'],
  ['tools/state-machine-docs','state-machine-docs'],
];

const DIAGRAM_DIRS = [
  ['diagrams/context-map',        'diagrams/context-map'],
  ['diagrams/sequence-diagrams',  'diagrams/sequence-diagrams'],
];

// ── Helpers ───────────────────────────────────────────────────────────────────

function gitListHtml(dir) {
  try {
    const out = execFileSync('git', ['ls-tree', '--name-only', `main:packages/explorer/${dir}`], {
      cwd: ROOT, encoding: 'utf8',
    });
    return out.trim().split('\n').filter(f => f.endsWith('.html'));
  } catch {
    return [];
  }
}

function gitExtract(gitPath, destPath) {
  try {
    const content = execFileSync('git', ['show', `main:${gitPath}`], {
      cwd: ROOT, encoding: 'buffer', maxBuffer: 64 * 1024 * 1024,
    });
    mkdirSync(dirname(destPath), { recursive: true });
    writeFileSync(destPath, content);
    return true;
  } catch {
    return false;
  }
}

function diffFiles(a, b) {
  const result = spawnSync('diff', ['-u', '--label', 'baseline', '--label', 'current', a, b], {
    encoding: 'utf8',
  });
  return { same: result.status === 0, output: result.stdout };
}

// ── Step 1: Extract baseline from git ─────────────────────────────────────────

console.log('Extracting baseline from main...');
mkdirSync(BASELINE_DIR, { recursive: true });

// Root hub
gitExtract('packages/explorer/index.html', join(BASELINE_DIR, 'index.html'));

const filePairs = [['index.html', 'index.html']];

for (const [baseDir, currentDir] of [...TOOL_DIRS, ...DIAGRAM_DIRS]) {
  const files = gitListHtml(baseDir);
  for (const f of files) {
    const gitPath  = `packages/explorer/${baseDir}/${f}`;
    const destPath = join(BASELINE_DIR, baseDir, f);
    gitExtract(gitPath, destPath);
    filePairs.push([join(baseDir, f), join(currentDir, f)]);
  }
}

console.log(`  Extracted ${filePairs.length} files.\n`);

// ── Step 2: Seed content dir with authored files, then build ─────────────────
// The build reads authored config from the content package (e.g.
// diagrams/context-map/config/config.yaml). Seed CURRENT_DIR from
// safety-net-explorer/ so those files are present before the build runs.

if (skipBuild) {
  console.log('Skipping build (--skip-build).\n');
} else {
  // Regenerate packages/generated/ from the current branch's contracts so it
  // matches what main had when the baseline HTML was committed. The local
  // resolved dir may be dirty (content from other branches).
  const resolvedDir = resolve(ROOT, 'packages', 'resolved');
  console.log('Regenerating packages/generated/ from current branch contracts...');
  execFileSync(node, [
    resolve(ROOT, 'packages', 'blueprint-cli', 'scripts', 'resolve.js'),
    `--spec=${resolve(ROOT, 'packages', 'safety-net-contracts')}`,
    `--out=${resolvedDir}`,
  ], { stdio: 'inherit', cwd: ROOT });

  const contentSrc = resolve(ROOT, 'packages', 'safety-net-explorer');
  console.log(`\nSeeding content dir from ${contentSrc}...`);
  mkdirSync(CURRENT_DIR, { recursive: true });
  cpSync(contentSrc, CURRENT_DIR, { recursive: true });

  console.log(`Building current branch into ${CURRENT_DIR}...`);
  execFileSync(node, [
    resolve(ROOT, 'packages', 'blueprint-explorer', 'build.js'),
    `--content=${CURRENT_DIR}`,
    `--resolved=${resolvedDir}`,
  ], { stdio: 'inherit', cwd: ROOT });
  console.log();
}

// ── Step 3: Diff ──────────────────────────────────────────────────────────────

console.log('Comparing files...\n');

let matched = 0, diffed = 0, missing = 0;
const diffedFiles = [];

for (const [basePath, currentPath] of filePairs) {
  const a = join(BASELINE_DIR, basePath);
  const b = join(CURRENT_DIR,  currentPath);
  const label = currentPath;

  if (!existsSync(b)) {
    console.log(`  MISSING  ${label}`);
    missing++;
    continue;
  }

  const { same, output } = diffFiles(a, b);
  if (same) {
    console.log(`  MATCH    ${label}`);
    matched++;
  } else {
    const lines = output.split('\n').length - 1;
    console.log(`  DIFF     ${label}  (${lines} line${lines !== 1 ? 's' : ''})`);
    diffedFiles.push({ label, output });
    diffed++;
  }
}

// ── Step 4: Summary ───────────────────────────────────────────────────────────

console.log(`
── Summary ──────────────────────────────────────────────────────────────
  Match:   ${matched}
  Diff:    ${diffed}
  Missing: ${missing}
  Total:   ${filePairs.length}
`);

if (diffed > 0 && verbose) {
  console.log('── Diffs ────────────────────────────────────────────────────────────────\n');
  for (const { label, output } of diffedFiles) {
    console.log(`=== ${label} ===`);
    console.log(output);
  }
} else if (diffed > 0) {
  console.log(`Run with --verbose to see full diff output, or:\n`);
  for (const { label } of diffedFiles) {
    const b = join(CURRENT_DIR, label);
    const a = join(BASELINE_DIR, label.replace(/^([^/]+)/, (_, seg) => {
      const match = [...TOOL_DIRS, ...DIAGRAM_DIRS].find(([, cur]) => cur === seg || cur.startsWith(seg));
      return match ? match[0] : seg;
    }));
    console.log(`  diff -u ${a} ${b}`);
  }
}
